<script setup lang="ts">
import { onMounted, ref } from 'vue'

const brandSet = ref<HTMLElement | null>(null)

onMounted(() => {
    if (!brandSet.value || brandSet.value.parentElement?.children.length !== 1) return

    const duplicate = brandSet.value.cloneNode(true) as HTMLElement
    duplicate.setAttribute('aria-hidden', 'true')
    duplicate.querySelectorAll('[id]').forEach((element) => {
        const oldId = element.id
        const newId = `${oldId}-copy`
        element.id = newId
        duplicate.querySelectorAll(`[clip-path="url(#${oldId})"]`).forEach((svg) => {
            svg.setAttribute('clip-path', `url(#${newId})`)
        })
    })
    brandSet.value.parentElement?.append(duplicate)
})
</script>
